def calculate_C_parity(n):
    """
    Calculates the count C for n using Red=Even, Blue=Odd coloring.
    """
    S = list(range(1, n + 1))
    R_even = [x for x in S if x % 2 == 0]
    B_odd = [x for x in S if x % 2 != 0]

    def count_triples(A):
        count = 0
        for x in A:
            for y in A:
                for z in A:
                    if (x + y + z) % n == 0:
                        count += 1
        return count

    C_R = count_triples(R_even)
    C_B = count_triples(B_odd)

    return C_R + C_B

