def count_monochromatic_triples(n, R):
    """
    Calculates the number of monochromatic triples (x, y, z) such that 
    x+y+z is divisible by n, assuming R is the set of residues corresponding to one color.
    """
    count = 0
    # Iterate over all triples of residues (k_x, k_y, k_z) from R
    for kx in R:
        for ky in R:
            for kz in R:
                if (kx + ky + kz) % n == 0:
                    count += 1
    return count

def solve():
    TARGET = 2007

    for n in range(1, 16):
        print(f"--- Testing n = {n} ---")
        found_for_n = False

        # Iterate over all possible subsets R of {0, 1, ..., n-1}
        # We use bitmasks to represent the subsets R.

        # The set of all residues is {0, 1, ..., n-1}
        all_residues = list(range(n))

        # Iterate through all 2^n subsets R
        for i in range(1 << n):
            R = []
            B = []
            for j in range(n):
                if (i >> j) & 1:
                    R.append(j)
                else:
                    B.append(j)

            # Calculate C_R
            C_R = count_monochromatic_triples(n, R)

            # Calculate C_B
            C_B = count_monochromatic_triples(n, B)

            total_count = C_R + C_B

            if total_count == TARGET:
                print(f"SUCCESS for n={n}!")
                print(f"  Coloring found: R corresponds to residues {R}, B corresponds to residues {B}.")
                print(f"  C_R = {C_R}, C_B = {C_B}. Total = {total_count}.")
                found_for_n = True
                break # Found a coloring for this n

