def calculate_C_mod3(n, color_assignment):
    """
    Calculates the count C for n using Modulo 3 coloring.
    color_assignment is a mapping: {0: color_0, 1: color_1, 2: color_2}
    where color_i is 'R' or 'B'.
    """
    S = list(range(1, n + 1))

    R_set = []
    B_set = []

    for x in S:
        residue = x % 3
        if color_assignment[residue] == 'R':
            R_set.append(x)
        else:
            B_set.append(x)

    def count_triples(A):
        count = 0
        for x in A:
            for y in A:
                for z in A:
                    if (x + y + z) % n == 0:
                        count += 1
        return count

    C_R = count_triples(R_set)
    C_B = count_triples(B_set)

    return C_R + C_B

